/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: launchPaused, expectRestoredPreferences
 *   Constants: albumPath, storageKey, sharedMedia
 * Tests
 *   - restores player preferences after reload and reopening without restoring playback
 *   - remembers native media volume and mute changes on the next document load
 *   - keeps player controls usable when browser storage is denied
 * @end-catalog */

import type { Page } from '@playwright/test';

import { catalogIds } from './fixtures/catalog';
import { installSignedOutApi } from './support/apiRoutes';
import { expect, test } from './support/test';

const albumPath = `/finitude/albums/${catalogIds.album}`;
const storageKey = 'finitude:player-preferences:v1';
const sharedMedia = 'video:not([data-video-preview])';

/** Starts a real browser stream, then pauses it so preference checks have no clock dependency. */
const launchPaused = async (page: Page) => {
  await page.getByRole('main').locator('header').getByRole('button', { name: 'Play', exact: true }).click();
  const controls = page.getByRole('region', { name: 'Now playing' })
    .getByRole('group', { name: 'Playback controls' });
  await controls.getByRole('button', { name: 'Pause', exact: true }).click();
  await expect(controls.getByRole('button', { name: 'Play', exact: true })).toBeVisible();
};

/** Checks restored controls before any queue or media element has been created. */
const expectRestoredPreferences = async (page: Page) => {
  const player = page.getByRole('region', { name: 'Now playing' });
  await expect(player.getByRole('slider', { name: 'Volume' })).toHaveValue('0.03');
  await expect(player.getByRole('button', { name: 'Unmute', exact: true })).toBeDisabled();
  await expect(player.getByRole('button', { name: 'Shuffle enabled. Turn shuffle off' }))
    .toHaveAttribute('aria-pressed', 'true');
  await expect(player.getByRole('button', { name: 'Repeat one enabled. Turn repeat off' }))
    .toHaveAttribute('aria-pressed', 'true');
  await expect(player.getByRole('group', { name: 'Playback controls' })
    .getByRole('button', { name: 'Play', exact: true })).toBeDisabled();
  await expect(player.getByRole('button', { name: 'Show Now Playing view' }))
    .toHaveAttribute('aria-expanded', 'false');
  await expect(page.locator(sharedMedia)).toHaveCount(0);
};

test('restores player preferences after reload and reopening without restoring playback', async ({ page, context }) => {
  await page.goto(albumPath);
  // Video playback temporarily opens its panel; the explicit closed choice must still survive reload.
  await page.getByRole('button', { name: 'Hide Now Playing view' }).click();
  await launchPaused(page);
  const player = page.getByRole('region', { name: 'Now playing' });
  const volume = player.getByRole('slider', { name: 'Volume' });
  await volume.press('Home');
  for (let step = 0; step < 3; step += 1) await volume.press('ArrowRight');
  await expect(volume).toHaveValue('0.03');
  await player.getByRole('button', { name: 'Mute', exact: true }).click();
  await player.getByRole('button', { name: 'Shuffle off. Turn shuffle on' }).click();
  await player.getByRole('button', { name: 'Repeat off. Turn on repeat all' }).click();
  await player.getByRole('button', { name: 'Repeat all enabled. Turn on repeat one' }).click();

  await expect.poll(() => page.evaluate(key => {
    const serialized = window.localStorage.getItem(key);
    return serialized === null ? null : JSON.parse(serialized);
  }, storageKey)).toEqual({
    version: 1, volume: 0.03, muted: true, shuffleEnabled: true, repeatMode: 'one'
  });

  await page.reload();
  await expectRestoredPreferences(page);
  await launchPaused(page);
  await expect.poll(() => page.locator(sharedMedia).evaluate((media: HTMLVideoElement) => ({
    volume: media.volume, muted: media.muted
  }))).toEqual({ volume: 0.03, muted: true });

  const reopened = await context.newPage();
  const reopenedApi = await installSignedOutApi(reopened);
  try {
    await page.close();
    await reopened.goto(albumPath);
    await expectRestoredPreferences(reopened);
    await launchPaused(reopened);
    await expect.poll(() => reopened.locator(sharedMedia).evaluate((media: HTMLVideoElement) => ({
      volume: media.volume, muted: media.muted
    }))).toEqual({ volume: 0.03, muted: true });
    expect(reopenedApi.unhandled).toEqual([]);
  } finally {
    await reopened.close();
  }
});

test('remembers native media volume and mute changes on the next document load', async ({ page }) => {
  await page.goto(albumPath);
  await launchPaused(page);
  await page.locator(sharedMedia).evaluate((media: HTMLVideoElement) => {
    media.volume = 0.42;
    media.muted = true;
  });
  const player = page.getByRole('region', { name: 'Now playing' });
  await expect(player.getByRole('slider', { name: 'Volume' })).toHaveValue('0.42');
  await expect(player.getByRole('button', { name: 'Unmute', exact: true })).toBeVisible();
  await page.reload();
  await expect(player.getByRole('slider', { name: 'Volume' })).toHaveValue('0.42');
  await expect(page.locator(sharedMedia)).toHaveCount(0);
  await launchPaused(page);
  await expect.poll(() => page.locator(sharedMedia).evaluate((media: HTMLVideoElement) => ({
    volume: media.volume, muted: media.muted
  }))).toEqual({ volume: 0.42, muted: true });
});

test('keeps player controls usable when browser storage is denied', async ({ page }) => {
  await page.addInitScript(() => {
    Object.defineProperty(window, 'localStorage', {
      configurable: true,
      get: () => { throw new DOMException('Storage is unavailable.', 'SecurityError'); }
    });
  });
  await page.goto(albumPath);
  await launchPaused(page);
  const player = page.getByRole('region', { name: 'Now playing' });
  const volume = player.getByRole('slider', { name: 'Volume' });
  await volume.press('Home');
  await volume.press('ArrowRight');
  await player.getByRole('button', { name: 'Mute', exact: true }).click();
  await player.getByRole('button', { name: 'Shuffle off. Turn shuffle on' }).click();
  await player.getByRole('button', { name: 'Repeat off. Turn on repeat all' }).click();
  await expect(volume).toHaveValue('0.01');
  await expect.poll(() => page.locator(sharedMedia).evaluate((media: HTMLVideoElement) => ({
    volume: media.volume, muted: media.muted
  }))).toEqual({ volume: 0.01, muted: true });
  await expect(player.getByRole('button', { name: 'Shuffle enabled. Turn shuffle off' }))
    .toHaveAttribute('aria-pressed', 'true');
  await expect(player.getByRole('button', { name: 'Repeat all enabled. Turn on repeat one' }))
    .toHaveAttribute('aria-pressed', 'true');
});
